function reprBytes(buf){
  const has27=buf.includes(0x27), has22=buf.includes(0x22);
  const q = (has27 && !has22) ? 0x22 : 0x27;
  let s="b"+String.fromCharCode(q);
  for(const b of buf){
    if(b===0x5c) s+="\\\\";
    else if(b===q) s+="\\"+String.fromCharCode(b);
    else if(b===0x09) s+="\\t";
    else if(b===0x0a) s+="\\n";
    else if(b===0x0d) s+="\\r";
    else if(b<0x20||b>=0x7f) s+="\\x"+b.toString(16).padStart(2,"0");
    else s+=String.fromCharCode(b);
  }
  return s+String.fromCharCode(q);
}
const fs=require('fs');
let bad=0,n=0;
for(const line of fs.readFileSync(process.argv[2],'utf8').split('\n')){
  if(!line.trim())continue;
  const [label,hex,obs]=line.split('\t');
  const exp=reprBytes(Buffer.from(hex,'hex'));
  n++;
  if(exp!==obs){bad++;console.log("MISMATCH",label,hex,"exp="+exp,"obs="+obs);}
}
console.log("checked="+n,"mismatches="+bad);
